function qtPattern(kind, size){
  var g = [];
  for(var y=0;y<size;y++){
    var row = [];
    for(var x=0;x<size;x++){
      var v;
      if(kind === 'gradient'){ v = ((x + y) / (2*size - 2)) * 255; }
      else if(kind === 'checker'){ v = ((Math.floor(x/(size/8)) + Math.floor(y/(size/8))) % 2) ? 220 : 40; }
      else { var dx = x - size/2, dy = y - size/2; v = (Math.sin(Math.sqrt(dx*dx+dy*dy) * 0.15) + 1) / 2 * 255; }
      row.push(v);
    }
    g.push(row);
  }
  return g;
}
function qtStats(grid, x, y, s){
  var sum = 0, sum2 = 0, n = s*s;
  for(var j=y;j<y+s;j++) for(var i=x;i<x+s;i++){ var v = grid[j][i]; sum += v; sum2 += v*v; }
  var mean = sum / n;
  return { mean: mean, std: Math.sqrt(Math.max(0, sum2/n - mean*mean)) };
}
function qtBuild(grid, x, y, s, thr, minSize){
  var st = qtStats(grid, x, y, s);
  if(s <= (minSize||4) || st.std <= thr){
    return { x:x, y:y, s:s, v: st.mean, leaf: true };
  }
  var h = s/2;
  return { x:x, y:y, s:s, leaf: false, kids: [
    qtBuild(grid, x, y, h, thr, minSize),
    qtBuild(grid, x+h, y, h, thr, minSize),
    qtBuild(grid, x, y+h, h, thr, minSize),
    qtBuild(grid, x+h, y+h, h, thr, minSize)
  ]};
}
function qtLeaves(node, out){
  out = out || [];
  if(node.leaf) out.push(node);
  else for(var i=0;i<4;i++) qtLeaves(node.kids[i], out);
  return out;
}
function qtCount(node){
  if(node.leaf) return { nodes: 1, leaves: 1, depth: 1 };
  var nodes = 1, leaves = 0, depth = 0;
  for(var i=0;i<4;i++){
    var c = qtCount(node.kids[i]);
    nodes += c.nodes; leaves += c.leaves; depth = Math.max(depth, c.depth);
  }
  return { nodes: nodes, leaves: leaves, depth: depth + 1 };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { qtPattern:qtPattern, qtStats:qtStats, qtBuild:qtBuild, qtLeaves:qtLeaves, qtCount:qtCount };
}
if (typeof window !== 'undefined') {
  window.QuadtreeForgePure = { qtPattern:qtPattern, qtStats:qtStats, qtBuild:qtBuild, qtLeaves:qtLeaves, qtCount:qtCount };
}
